{
  "title": "Choosing the Level of Command Control",
  "setting": "Military command, in the doctrinal context of ADP 6-0 dated 31 July 2019.",
  "decider": "The Commander",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The Commander",
  "agent_role": "decide",
  "situation": "A Commander is determining the level of control over subordinate elements. The operation or phase may call for close synchronization, or may leave room for subordinate initiative. The Commander has to account for mission variables and other considerations, including risk, legal and ethical ambiguity, rules of engagement, training, trust, and shared understanding. Control can be reassessed as the situation evolves. Subordinates may need to address unexpected problems and act on the commander's intent.",
  "question": "What should the Commander do about the level of control over subordinate elements?",
  "facts": [
    {
      "id": "F1",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Determining the appropriate level of control includes decisions about delegation and decentralized execution.",
      "spans": [
        "src:e198456499eb#p17.6"
      ]
    },
    {
      "id": "F2",
      "kind": "situation",
      "status": "confirmed",
      "fact": "The level and application of control evolve and should be continuously assessed and adjusted to the situation.",
      "spans": [
        "src:e198456499eb#p17.6"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Subordinates should have the greatest freedom of action commensurate with acceptable risk.",
      "spans": [
        "src:e198456499eb#p17.6"
      ]
    },
    {
      "id": "F4",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Mission variables include mission, enemy, terrain and weather, available troops and support, available time, and civil considerations.",
      "spans": [
        "src:e198456499eb#p17.6"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Other control considerations include enemy disposition and capabilities, required synchronization and integration, higher-echelon constraints, and risk.",
      "spans": [
        "src:e198456499eb#p17.6"
      ]
    },
    {
      "id": "F6",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Legal and ethical ambiguity, rules of engagement, unit cohesion, training, trust, and shared understanding are also control considerations.",
      "spans": [
        "src:e198456499eb#p18.2"
      ]
    },
    {
      "id": "F7",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Operations requiring close synchronization or integration of effects in limited time may require detailed coordination and more centralized control.",
      "spans": [
        "src:e198456499eb#p18.2"
      ]
    },
    {
      "id": "F8",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Operations not requiring close coordination can offer opportunities for initiative that may be lost through excessive detailed synchronization.",
      "spans": [
        "src:e198456499eb#p18.2"
      ]
    },
    {
      "id": "F9",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Even in highly controlled operations, subordinates must address unexpected problems and pursue the commander's intent when existing orders no longer fit the circumstances.",
      "spans": [
        "src:e198456499eb#p18.2"
      ]
    }
  ],
